        let output = to_toggle_case(&input);
        // 'R' -> 'r', 'u' -> 'U', 's' -> 'S', 't' -> 'T'; digits, punctuation,
        // space, non-ASCII Ф remain the same
        let expected: Vec<char> = "rUST123! Ф".chars().collect();
        assert_eq!(output, expected);
